import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import toast from 'react-hot-toast';

const AuthPages = () => {
    const [isLogin, setIsLogin] = useState(true);
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        fullName: '',
        username: '',
        email: '',
        password: ''
    });

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        const endpoint = isLogin ? '/api/auth/login' : '/api/auth/register';

        try {
            const response = await axios.post(
                `http://localhost:8081${endpoint}`,
                isLogin 
                    ? { username: formData.username, password: formData.password }
                    : { 
                        fullName: formData.fullName, 
                        username: formData.username, 
                        email: formData.email, 
                        password: formData.password 
                    }
            );

            if (response.data) {
                localStorage.setItem('token', response.data.token); 
                localStorage.setItem('user', JSON.stringify(response.data.user || response.data));

                toast.success(isLogin ? 'Welcome back!' : 'Account created! 🎉');
                
                // SUCCESS FLOW: Redirect to Tracker
                navigate('/tracker');
            }
        } catch (error) {
            console.error("Auth Error:", error.response?.data || error.message);
            let errorMsg = error.response?.data?.message || error.response?.data || 'Something went wrong.';
            toast.error(errorMsg);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={{ 
            minHeight: '100vh', 
            display: 'flex', 
            justifyContent: 'center', 
            alignItems: 'center', 
            background: '#f0f2f5' 
        }}>
            <div style={{ 
                background: 'white', 
                padding: '40px', 
                borderRadius: '12px', 
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)', 
                width: '100%', 
                maxWidth: '400px' 
            }}>
                <h2 style={{ textAlign: 'center', marginBottom: '20px' }}>
                    {isLogin ? 'Login' : 'Create Account'}
                </h2>
                
                <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    
                    {!isLogin && (
                        <input 
                            type="text" 
                            name="fullName"
                            placeholder="Full Name" 
                            value={formData.fullName}
                            onChange={handleChange}
                            style={{ padding: '12px', borderRadius: '6px', border: '1px solid #ddd' }}
                            required
                        />
                    )}

                    <input 
                        type="text" 
                        name="username"
                        placeholder="Username" 
                        value={formData.username}
                        onChange={handleChange}
                        style={{ padding: '12px', borderRadius: '6px', border: '1px solid #ddd' }}
                        required
                    />

                    {!isLogin && (
                        <input 
                            type="email" 
                            name="email"
                            placeholder="Email address" 
                            value={formData.email}
                            onChange={handleChange}
                            style={{ padding: '12px', borderRadius: '6px', border: '1px solid #ddd' }}
                            required
                        />
                    )}

                    <input 
                        type="password" 
                        name="password"
                        placeholder="Password" 
                        value={formData.password}
                        onChange={handleChange}
                        style={{ padding: '12px', borderRadius: '6px', border: '1px solid #ddd' }}
                        required
                    />

                    <button 
                        type="submit" 
                        disabled={loading}
                        style={{ 
                            padding: '12px', 
                            borderRadius: '6px', 
                            border: 'none', 
                            background: '#7B61FF', 
                            color: 'white', 
                            fontWeight: 'bold', 
                            cursor: 'pointer',
                            opacity: loading ? 0.7 : 1
                        }}
                    >
                        {loading ? 'Processing...' : (isLogin ? 'Login' : 'Create Account')}
                    </button>
                </form>

                <div style={{ textAlign: 'center', marginTop: '15px' }}>
                    <button 
                        type="button"
                        onClick={() => {
                            setIsLogin(!isLogin);
                            setFormData({ fullName: '', username: '', email: '', password: '' });
                        }}
                        style={{ border: 'none', background: 'none', color: '#7B61FF', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        {isLogin ? 'Create a new account' : 'Already have an account? Login'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AuthPages;
